		foreach ($messageData['parameters'] as $placeholder => $parameter) {
			$placeholders[] = '{' . $placeholder . '}';
			if ($parameter['type'] === 'user') {
				if (str_contains($parameter['id'], ' ') || str_contains($parameter['id'], '/')) {
					$replacements[] = '@"' . $parameter['id'] . '"';
